from pathlib import Path
import json,re,hashlib
S=Path(__file__).resolve().parent
E=S.parent/'editorial/book_revision'; E.mkdir(parents=True,exist_ok=True)
changes=[]
def edit(rel, replacements=(), transform=None):
 p=S/rel; old=p.read_text(); new=old
 for a,b in replacements:
  if a not in new:
   if b in new: continue
   raise ValueError(f'missing exact edit in {rel}: {a[:120]}')
  new=new.replace(a,b)
 if transform: new=transform(new)
 if new==old:return
 backup=S/'book_revision_before'/rel; backup.parent.mkdir(parents=True,exist_ok=True)
 if not backup.exists():backup.write_bytes(p.read_bytes())
 p.write_text(new)
 changes.append({'file':rel,'before_sha256':hashlib.sha256(old.encode()).hexdigest(),'after_sha256':hashlib.sha256(new.encode()).hexdigest()})
