for item in inv:
 if item['paper'] not in ['I','II']:continue
 for rel in item['active_editable_inputs']:
  if not rel.endswith('.tex') or '/visual_graphics/' in rel or rel.endswith('core-layout.tex') or '/generated/theorem_map.' in rel or '/generated/release_catalog.' in rel:continue
  if not (S/rel).exists():continue
  def clean(t,chapter=item['paper']):
   t=re.sub(r'(\\renewcommand\{\\KomorebiEdition\})\{[^\n]*\}',r'\1{}',t)
   t=t.replace('\\KomorebiKind}{Monograph edition}','\\KomorebiKind}{Mathematical text}').replace('\\KomorebiKind}{Modern Monograph}','\\KomorebiKind}{Mathematical text}')
   t=t.replace('\\KomorebiSeries}{Core series '+chapter+'}','\\KomorebiSeries}{Chapter '+chapter+'}')
   t=re.sub(r'\bPaper '+chapter+r'\b','Chapter '+chapter,t)
   t=t.replace('Traditional paper:','Chapter '+chapter+', mathematical text:')
   if 'atlas' in rel or 'pages_final' in rel or 'Visual_Guide' in rel or 'Traditional_Final' in rel:
    t=re.sub(r'(?<![A-Za-z0-9_/])V([1-9][0-9]*)(?![A-Za-z0-9_])',lambda m:'Plate '+chapter+'.'+m[1],t)
    t=t.replace('V#1','Plate '+chapter+'.#1')
   return t
  edit(rel,transform=clean)
